using System.Collections;
using System.Collections.Generic;
using System.Runtime.CompilerServices;
using UnityEngine;

public class LerpSkybox1 : MonoBehaviour
{

    [SerializeField]
    private Texture2D DaySkybox;
    [SerializeField]
    private Texture2D LunchSkybox;
    [SerializeField]
    private Texture2D NightSkybox;
    [SerializeField]
    private Light MapLight;
    [SerializeField]
    private float LerpTime = 45f;
    [SerializeField]
    private float RotateTime = 480f;

    [SerializeField]
    private Gradient DayToLunch;
    [SerializeField]
    private Gradient LunchToNight;


    private Coroutine RotateCoroutine;
    private Coroutine DayCoroutine;
    private Coroutine LightCoroutine;
    private Coroutine CounterCoroutine;
    //코루틴 중단을 위한 인스턴스화

    void Start()
    {
        ResetSkybox();
        RotateCoroutine = StartCoroutine(RotateSkybox());
        CounterCoroutine = StartCoroutine(DayCounter());
        //하늘 색 변하는 코루틴, 하늘 회전하는 코루틴
    }

    void Update()
    {
        //if (Input.GetKeyDown(KeyCode.A))
        //{
        //    StopDayCycle(); 
        //    //모든 동작중인 코루틴을 정지하는 메소드
        //}
    }

    private IEnumerator DayCounter()
    {
        //50초 이상에 돌입 시 45초동안 저녁노을, 145초 이상에 돌입 시 45초동안 밤 스카이박스로 전환

        float t = 0;

        int DayCount = 0;
        int LunchCount = 0;
        while(t < 241)
        {
            t+=Time.deltaTime;
            if(t > 50 && DayCount == 0)
            {
                RenderSettings.skybox.SetFloat("_Exposure2", 1f);
                DayCoroutine = StartCoroutine(SkyboxCorutine(DaySkybox, LunchSkybox, LerpTime));
                LightCoroutine = StartCoroutine(LerpLight(DayToLunch, LerpTime));
                DayCount = 1;
            }

            if(t > 145 && LunchCount == 0)
            {
                RenderSettings.skybox.SetFloat("_Exposure2", 0.5f);
                DayCoroutine = StartCoroutine(SkyboxCorutine(LunchSkybox, NightSkybox, LerpTime));
                LightCoroutine = StartCoroutine(LerpLight(LunchToNight, LerpTime));
                LunchCount = 1;
            }
            Debug.Log(t);
            yield return null;
        }
    }

    private IEnumerator SkyboxCorutine(Texture2D Start, Texture2D End, float time) //스카이박스 텍스처 보간 코루탄
    {
        float t = 0;
        RenderSettings.skybox.SetTexture("_Texture1", Start);
        RenderSettings.skybox.SetTexture("_Texture2", End);
        RenderSettings.skybox.SetFloat("_Blend", 0);
        while (t<time)
        {
            t += Time.deltaTime;

            RenderSettings.skybox.SetFloat("_Blend", t / time);
            yield return null;
        }
        
    }


    private IEnumerator RotateSkybox() //스카이박스 회전 코루틴
    {
        float t = 0;

        while(true)//초당 1/360만큼 회전
        {
            t += Time.deltaTime;
            RenderSettings.skybox.SetFloat("_Rotation1", t );
            RenderSettings.skybox.SetFloat("_Rotation2", t );
            if (t >= 360) t = 0;
            yield return null;
        }
    }

    private void ResetSkybox() //아침으로 스카이박스 리셋
    {
        RenderSettings.skybox.SetFloat("_Blend", 0f);
        RenderSettings.skybox.SetFloat("_Rotation1", 0f);
        RenderSettings.skybox.SetFloat("_Rotation2", 0f);
        RenderSettings.skybox.SetTexture("_Texture1", DaySkybox);
        RenderSettings.skybox.SetTexture("_Texture2", LunchSkybox);
    }

    private IEnumerator LerpLight(Gradient LightGradient, float time)
    {
        //색상 값을 그레디언트 중 현재 시간에 맞는 값을 가져옴
        float t = 0;

        while(t<time)
        {
            t += Time.deltaTime;
            MapLight.color = LightGradient.Evaluate(t / time);
            yield return null;
        }
        
    }

    private void StopDayCycle()
    {
        //인스턴스화한 코루틴들을 정지시킴

        if (CounterCoroutine != null) StopCoroutine(CounterCoroutine);
        //if (RotateCoroutine != null) StopCoroutine(RotateCoroutine);
        if (DayCoroutine != null) StopCoroutine(DayCoroutine);
        if (LightCoroutine != null) StopCoroutine(LightCoroutine);

    }


}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            
